		#region UnassignLines

		void UnassignLines()
		{
			if (Transfer is IMasterStaffAssigner transfer)
			{
				if (transfer.CanAssignOrUnAssignAnyLines)
				{
					foreach (var line in transfer.Lines.Where(l => l.CanAssignOrUnAssignLine()))
					{
						line.UnAssignLine(null);
					}
				}
				else
				{
					Globals.Message.ShowError(NoAssignedLinesErrorMessage);
				}
			}
		}

		string NoAssignedLinesErrorMessage => Res.GetString("2115afba-4b49-4acd-bcc7-370f233f213a", "No lines can be un-assigned. There are no lines with empty Picked Time, or Picking has already commenced.");

		#endregion

		#region Assign Lines to user

		void AssignLines(AssignLineOptions option)
		{
			using (new DocketNotificationSubscriberWithWaitCursor(Docket, GetNotificationBuffer()))
			{
				var transfer = ((WhsTransfer)Docket);
				transfer.Option = option;

				var transferLines = transfer.Lines.Cast<ILineStaffAssigner>();
				if (transferLines.Any(l => l.CanAssignOrUnAssignLine()))
				{
					var attacher = new AssignLinesToUserAttacher<ILineStaffAssigner>(transferLines.Where(l => l.CanAssignOrUnAssignLine()), transfer.Factory);
					attacher.Show(this);
#if DEBUG
					LastShownTransferLineAttachPopupForTesting = attacher.LastShownAttachPopupForTesting;
					TransferLineAttacherForTesting = attacher;
#endif
				}
				else
				{
					Globals.Message.ShowError(NoUnAssignedLinesMessage());
				}
			}
		}

#if DEBUG
		public EmbeddedModulePopup LastShownTransferLineAttachPopupForTesting;
		public AssignLinesToUserAttacher<ILineStaffAssigner> TransferLineAttacherForTesting;
#endif

