		#region Implementation

		BusinessObject[] GetCollectionFromGrid()
		{
			BusinessObject[] list = null;
			if (TransferDocketLinesGridUserControl != null)
			{
				ZGrid grid = TransferDocketLinesGridUserControl.LinesGrid;
				if (grid != null && grid.List != null && grid.ListManager != null)
				{
					if (grid.SelectedElements.Length > 0)
					{
						list = grid.SelectedElements;
					}
					else
					{
						list = new BusinessObject[grid.List.Count];
						grid.List.CopyTo(list, 0);
					}
				}
			}
			return list;
		}

