		#region Finalise Button

		protected void FinaliseButton_Click(object sender, EventArgs e)
		{
			if (Env.Security.WhsTransferFinalise.IsAllowed)
			{
				if (ValidateAndSaveHandlingConcurrencyException() == ContinueWithSave.Yes)
				{
					FinaliseJobFormHelper.FinaliseDocket(Docket, this, GetNotificationBuffer());
				}
			}
			else
			{
				Env.Security.ShowError(Env.Security.WhsTransferFinalise);
			}
		}

		ContinueWithSave ValidateAndSaveHandlingConcurrencyException()
		{
			var result = ContinueWithSave.No;
			try
			{
				result = ValidateAndSave();
			}
			catch (Exception ex) when (!ex.IsCriticalException())
			{
				HandleSaveException(ex);
			}
			return result;
		}

		#endregion

